def header(prefix=''):
 return f'''<a class="skip" href="#main">Skip to content</a><header class="site-header wrap"><a class="brand" href="{prefix}index.html"><span class="brand-icon" aria-hidden="true">CK</span><span>Chamindu Kaushalye</span></a><nav aria-label="Main"><a href="{prefix}index.html#work">Work</a><a href="{prefix}index.html#about">About</a><a href="{prefix}cv.html">CV</a><a href="{prefix}index.html#contact">Contact</a><button class="theme-toggle" type="button" hidden>Light theme</button></nav></header>'''

def footer(prefix=''):
 return f'''<footer class="wrap"><span>Chamindu Kaushalye · Built with care.</span><div><a href="{GITHUB}">GitHub</a><a href="{LINKEDIN}">LinkedIn</a><a href="{prefix}assets/Chamindu-Kaushalye-CV.pdf" download>Download CV</a></div></footer>'''

def page(title, description, body, path='index.html', prefix='', extra=''):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | Chamindu Kaushalye</title><meta name="description" content="{escape(description,quote=True)}"><meta name="theme-color" content="#101b30"><meta property="og:title" content="{escape(title,quote=True)} | Chamindu Kaushalye"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{BASE+path}"><meta property="og:image" content="{BASE}assets/pos-checkout.png"><meta name="twitter:card" content="summary_large_image"><link rel="canonical" href="{BASE+path}"><link rel="icon" href="{prefix}favicon.svg"><link rel="stylesheet" href="{prefix}style.css"><script src="{prefix}script.js" defer></script>{extra}</head><body>{header(prefix)}{body}{footer(prefix)}</body></html>'''

def image(p, index=0, prefix='', lightbox=False):
 file,label,alt=p['images'][index]
 width,height=struct.unpack('>II',(ROOT/'assets'/file).read_bytes()[16:24])
 return f'''<figure class="screen"><a href="{prefix}assets/{file}" {'data-gallery-item' if lightbox else ''}><img src="{prefix}assets/{file}" alt="{escape(alt)}" loading="lazy" width="{width}" height="{height}"></a><figcaption>{label} <span>Demo data{' · Click to enlarge' if lightbox else ''}</span></figcaption></figure>'''

def card(p, featured=False):
 preview=image(p) if p['images'] else '<div class="search-illustration" aria-label="Search workflow diagram"><span>Describe the lost item</span><span aria-hidden="true">↓</span><strong>Search reported items</strong><span aria-hidden="true">↓</span><span>Explore relevant reports</span></div>'
 # Homepage preview links lead to the case study, not directly to an image.
 if p['images']: preview=preview.replace(f'href="assets/{p["images"][0][0]}"',f'href="projects/{p["slug"]}.html"')
 return f'''<article id="{p['slug']}" class="project {p['color']} {'featured' if featured else ''}"><div class="project-copy"><p class="kicker">{p['category']}</p><h3><a href="projects/{p['slug']}.html">{p['name']}</a></h3><p class="project-headline">{p['headline']}</p><p>{p['summary']}</p><ul class="tags">{''.join('<li>'+s+'</li>' for s in p['stack'])}</ul><a class="text-link" href="projects/{p['slug']}.html">Explore case study <span aria-hidden="true">↗</span></a></div>{preview}</article>'''

